import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def get_integer_root(N, e):
    if e == 1:
        return N
    # Estimate p using the e-th root
    p_approx = round(N**(1/e))
    # Check around the approximation
    for p in range(max(2, p_approx - 2), p_approx + 3):
        if p**e == N:
            return p
    return None

solutions = []
# Search up to e=15 as exponential growth dominates linear growth quickly
for e in range(1, 16):
    N = 12 * e + 1

    # Check if N is a perfect e-th power
    p = get_integer_root(N, e)

    if p is not None:
        # Check if the base p is prime
        if is_prime(p):
            solutions.append((p, e))
            print(f"Found solution for e={e}: p={p}, N={N}")

print(f"All solutions found up to e=15: {solutions}")

