import math

def solve_k2(e1, e2):
    """
    Solves p1^e1 * p2^e2 = (12*e1 + 1) * (12*e2 + 1) for distinct primes p1, p2.
    """
    RHS = (12 * e1 + 1) * (12 * e2 + 1)

    # Factor RHS
    factors = {}
    d = 2
    temp_RHS = RHS
    while d * d <= temp_RHS:
        while temp_RHS % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_RHS //= d
        d += 1
    if temp_RHS > 1:
        factors[temp_RHS] = factors.get(temp_RHS, 0) + 1

    print(f"--- Testing (e1={e1}, e2={e2}) ---")
    print(f"RHS = {RHS}. Prime factorization of RHS: {factors}")

    # We need to partition the factors of RHS into two parts, P1 and P2,
    # such that P1 = p1^e1 and P2 = p2^e2, where p1 and p2 are primes.

    # Case (1, 1)
    if e1 == 1 and e2 == 1:
        if len(factors) == 1 and list(factors.values())[0] == 2:
            p = list(factors.keys())[0]
            print(f"RHS is p^2. Requires p1=p2={p}. No distinct solution.")
        else:
            print("RHS cannot be factored into p1*p2 where p1 != p2.")
        return []

    # General case: iterate through possible prime bases p1
    solutions = []

    # p1 must be a factor of RHS, and p1^e1 must divide RHS
    for p1 in factors.keys():
        if p1**e1 > RHS:
            continue

        # Check if p1^e1 divides RHS
        if RHS % (p1**e1) != 0:
            continue

        P2 = RHS // (p1**e1)

        # Now, check if P2 can be written as p2^e2 for some prime p2

        # Check for e2=1
        if e2 == 1:
            if P2 > 1 and all(P2 % d != 0 for d in range(2, int(math.sqrt(P2)) + 1)):
                p2 = P2
                if p2 != p1:
                    solutions.append((p1, e1, p2, e2))

        # Check for e2=2
        elif e2 == 2 and math.isqrt(P2) ** 2 == P2:
            p2 = math.isqrt(P2)
            if p2 > 1 and p2 != p1:
                solutions.append((p1, e1, p2, e2))

        # Check for e2=3 (e.g., 2^3=8)
        elif e2 == 3:
            if P2 > 0 and P2 == 1: continue
            p2_candidate = round(P2**(1/3))
            if p2_candidate**3 == P2 and p2_candidate > 1 and p2_candidate != p1:
                 solutions.append((p1, e1, p2_candidate, e2))

    return solutions

# Test cases
test_cases = [(1, 1), (2, 1), (1, 2), (2, 2)]
all_solutions = []

for e1, e2 in test_cases:
    sols = solve_k2(e1, e2)
    all_solutions.extend(sols)

print("\n===== Summary of Results =====")
if all_solutions:
    print("Found solutions (p1, e1, p2, e2):")
    for sol in all_solutions:
        p1, e1, p2, e2 = sol
        n = p1**e1 * p2**e2
        print(f"  Solution: n = {p1}^{e1} * {p2}^{e2} = {n}")
else:
    print("No distinct prime solutions found for the tested exponent pairs.")

